window.AUG26_STORE = {
  sheetId: '1XjhjiG6mIPXmOOykL4iq4TaSjpr2IPDgZjvPNscNmrg',
  tabs: ['IBNR', 'E-PAYMENT', 'RTO', 'INS /FORM20', 'DELIVERED'],
  records: [],

  init() {
    const saved = localStorage.getItem('AUG26_RECORDS_V5');
    if (saved) {
      try {
        this.records = JSON.parse(saved);
      } catch (e) {
        this.records = INITIAL_LIVE_RECORDS;
      }
    } else {
      this.records = INITIAL_LIVE_RECORDS;
      this.save();
    }
  },

  save() {
    try {
      localStorage.setItem('AUG26_RECORDS_V5', JSON.stringify(this.records));
    } catch(e) {
      console.warn('Storage quota exceeded', e);
    }
  },

  resetToDefault() {
    this.records = INITIAL_LIVE_RECORDS;
    this.save();
  },

  setRecords(newRecords) {
    this.records = newRecords;
    this.save();
  },

  addOrReplaceTabRecords(tabName, newRecords) {
    this.records = this.records.filter(r => r.stage.toUpperCase() !== tabName.toUpperCase());
    this.records.push(...newRecords);
    this.save();
  }
};

